DECLARE payload jsonb := $payload$[{"language": "es", "slug": "leche-evaporada-casera", "public_path": "/leche-evaporada-casera", "title": "Leche evaporada casera sin azúcar añadido", "excerpt": "Prepara leche evaporada casera reduciendo leche entera sin azúcar. Fotos, volumen final, tiempo de cocción y conservación para salsas, cremas y postres.", "summary": "La leche se concentra por evaporación hasta quedar aproximadamente el 40 % del volumen inicial. De 1 litro salen unos 400 ml, sin añadir azúcar ni harina. Esta versión casera necesita nevera y no tiene la esterilización de una lata comercial.", "content_html": "<p>La leche se concentra por evaporación hasta quedar aproximadamente el 40 % del volumen inicial. De 1 litro salen unos 400 ml, sin añadir azúcar ni harina. Esta versión casera necesita nevera y no tiene la esterilización de una lata comercial.</p>", "notes": "<h3>Consejos y conservación</h3><p>Usa tapada en 3–4 días. No monta como crema de leche y no reemplaza la leche condensada azucarada sin ajustar la receta. El tiempo depende de la anchura de la olla; manda el volumen final. Ficha sin prueba de cocina propia. Contiene leche. Usa utensilios limpios y desinfectados y conserva a 4 °C o menos. No es una conserva para guardar a temperatura ambiente.</p><ul><li><a href=\"https://www.biggerbolderbaking.com/evaporated-milk-recipe/\">Bigger Bolder Baking — evaporated milk technique</a></li><li><a href=\"https://asbe.org/article/evaporated-milk/?topic=ingredient\">American Society of Baking — evaporated milk</a></li></ul>", "ingredients": [{"name": "leche entera pasteurizada", "amount": "1000", "unit": "ml"}], "steps": [{"title": "Mide la leche", "content": "Pon el litro de leche en una olla ancha de fondo grueso. Para orientarte, mide antes cómo se ven 400 ml en esa olla o ten una jarra graduada resistente al calor.", "image_url": "https://manualdecocina.com/recetas/leche-evaporada-casera/paso-01.webp", "image_alt": "Mide la leche — Leche evaporada casera sin azúcar añadido"}, {"title": "Reduce suavemente", "content": "Calienta sin tapar a fuego bajo, manteniendo un hervor muy suave durante unos 40–50 minutos. Remueve el fondo con frecuencia y retira la película si aparece. No dejes que se queme o se desborde.", "image_url": "https://manualdecocina.com/recetas/leche-evaporada-casera/paso-02.webp", "image_alt": "Reduce suavemente — Leche evaporada casera sin azúcar añadido"}, {"title": "Comprueba y enfría", "content": "Cuando se acerque a 400 ml, comprueba el volumen con cuidado. Si sobra, reduce algo más; si te pasaste, añade un poco de leche. Pasa por colador fino a una jarra limpia y enfría en baño de agua fría sin dejar entrar agua.", "image_url": "https://manualdecocina.com/recetas/leche-evaporada-casera/paso-03.webp", "image_alt": "Comprueba y enfría — Leche evaporada casera sin azúcar añadido"}, {"title": "Refrigera y utiliza", "content": "Lleva a la nevera antes de 2 horas y deja enfriar aproximadamente 1 hora. Remueve antes de usar en salsas o postres. Queda más cremosa que la leche pero sigue siendo líquida.", "image_url": "https://manualdecocina.com/recetas/leche-evaporada-casera/paso-04.webp", "image_alt": "Refrigera y utiliza — Leche evaporada casera sin azúcar añadido"}], "category": "Guarniciones", "course": "Guarniciones", "cuisine": "Internacional", "difficulty": "Fácil", "prep_time_minutes": 5, "cook_time_minutes": 50, "total_time_minutes": 115, "servings": 8, "image_url": "https://manualdecocina.com/recetas/leche-evaporada-casera/portada.webp", "gallery": [{"url": "https://manualdecocina.com/recetas/leche-evaporada-casera/portada.webp", "alt": "Leche evaporada casera sin azúcar añadido"}], "video_urls": [], "keywords": ["Leche evaporada casera sin azúcar añadido"], "nutrition": {"calories": 79, "protein_g": 4.1, "carbs_g": 6.2, "fat_g": 4.2, "serving_size": "1 de 8 porciones, unos 50 ml", "estimated": true, "note": "Estimación por porción; el rendimiento, la humedad y la marca cambian los valores.", "source": "USDA FoodData Central generic whole milk", "method": "1000 ml milk estimated as 1030 g × per-100-g profile (61 kcal,3.15 g protein,4.8 g carbohydrate,3.25 g fat), divided by 8 portions. Finished volume about 400 ml, 50 ml per portion. Only water evaporates; no whey drained. Rounded."}, "seo": {"title": "Leche evaporada casera sin azúcar añadido", "description": "Prepara leche evaporada casera reduciendo leche entera sin azúcar. Fotos, volumen final, tiempo de cocción y conservación para salsas, cremas y postres.", "author": "Néstor Bastidas", "image_alt": "Leche evaporada casera sin azúcar añadido", "image_variants": ["https://manualdecocina.com/recetas/leche-evaporada-casera/portada-1x1.webp", "https://manualdecocina.com/recetas/leche-evaporada-casera/portada-4x3.webp", "https://manualdecocina.com/recetas/leche-evaporada-casera/portada-16x9.webp"], "faq": [{"q": "¿Lleva azúcar?", "a": "No se añade azúcar, pero conserva los azúcares naturales de la leche. No es un producto sin lactosa."}, {"q": "¿Puedo guardarla como una lata cerrada?", "a": "No. El proceso doméstico concentra la leche pero no la esteriliza para guardarla a temperatura ambiente."}], "additional_time_minutes": 60}, "published": false, "editorial_status": "ready"}, {"language": "en", "slug": "homemade-unsweetened-evaporated-milk", "public_path": "/en/homemade-unsweetened-evaporated-milk", "title": "Homemade evaporated milk without added sugar", "excerpt": "Make evaporated milk by gently reducing whole milk without sugar. Photos explain final volume, cooking time and cold storage for sauces, soups and desserts.", "summary": "Evaporation concentrates milk to about 40% of its starting volume. One litre yields roughly 400 ml without added sugar or flour. This homemade version needs refrigeration and is not sterilized like a commercial can.", "content_html": "<p>Evaporation concentrates milk to about 40% of its starting volume. One litre yields roughly 400 ml without added sugar or flour. This homemade version needs refrigeration and is not sterilized like a commercial can.</p>", "notes": "<h3>Tips and storage</h3><p>Keep covered and use within 3–4 days. It does not whip like heavy cream or replace sweetened condensed milk without recipe adjustments. Pan width affects timing; use final volume as your guide. Not kitchen-tested. Contains milk. Use clean, sanitized equipment and refrigerate at 4 °C or below. This is not a shelf-stable canned product.</p><ul><li><a href=\"https://www.biggerbolderbaking.com/evaporated-milk-recipe/\">Bigger Bolder Baking — evaporated milk technique</a></li><li><a href=\"https://asbe.org/article/evaporated-milk/?topic=ingredient\">American Society of Baking — evaporated milk</a></li></ul>", "ingredients": [{"name": "pasteurized whole milk", "amount": "1000", "unit": "ml"}], "steps": [{"title": "Measure the milk", "content": "Pour the litre into a wide heavy-based saucepan. First note what 400 ml looks like in that pot, or have a heatproof graduated jug ready.", "image_url": "https://manualdecocina.com/recetas/leche-evaporada-casera/paso-01.webp", "image_alt": "Measure the milk — Homemade evaporated milk without added sugar"}, {"title": "Reduce gently", "content": "Heat uncovered over low heat at a very gentle simmer for about 40–50 minutes. Stir the bottom regularly and remove any skin. Avoid scorching or boiling over.", "image_url": "https://manualdecocina.com/recetas/leche-evaporada-casera/paso-02.webp", "image_alt": "Reduce gently — Homemade evaporated milk without added sugar"}, {"title": "Check and cool", "content": "When near 400 ml, carefully check the volume. Reduce longer if necessary; add a little milk if over-reduced. Strain into a clean jug and cool in a cold-water bath without letting water enter.", "image_url": "https://manualdecocina.com/recetas/leche-evaporada-casera/paso-03.webp", "image_alt": "Check and cool — Homemade evaporated milk without added sugar"}, {"title": "Refrigerate and use", "content": "Refrigerate within 2 hours and allow about 1 hour to cool. Stir before using in sauces or desserts. It is creamier than milk but still fluid.", "image_url": "https://manualdecocina.com/recetas/leche-evaporada-casera/paso-04.webp", "image_alt": "Refrigerate and use — Homemade evaporated milk without added sugar"}], "category": "Side dishes", "course": "Side dishes", "cuisine": "International", "difficulty": "Easy", "prep_time_minutes": 5, "cook_time_minutes": 50, "total_time_minutes": 115, "servings": 8, "image_url": "https://manualdecocina.com/recetas/leche-evaporada-casera/portada.webp", "gallery": [{"url": "https://manualdecocina.com/recetas/leche-evaporada-casera/portada.webp", "alt": "Homemade evaporated milk without added sugar"}], "video_urls": [], "keywords": ["Homemade evaporated milk without added sugar"], "nutrition": {"calories": 79, "protein_g": 4.1, "carbs_g": 6.2, "fat_g": 4.2, "serving_size": "1 of 8 servings, about 50 ml", "estimated": true, "note": "Estimated per serving; yield, moisture and brands affect the values.", "source": "USDA FoodData Central generic whole milk", "method": "1000 ml milk estimated as 1030 g × per-100-g profile (61 kcal,3.15 g protein,4.8 g carbohydrate,3.25 g fat), divided by 8 portions. Finished volume about 400 ml, 50 ml per portion. Only water evaporates; no whey drained. Rounded."}, "seo": {"title": "Homemade evaporated milk without added sugar", "description": "Make evaporated milk by gently reducing whole milk without sugar. Photos explain final volume, cooking time and cold storage for sauces, soups and desserts.", "author": "Néstor Bastidas", "image_alt": "Homemade evaporated milk without added sugar", "image_variants": ["https://manualdecocina.com/recetas/leche-evaporada-casera/portada-1x1.webp", "https://manualdecocina.com/recetas/leche-evaporada-casera/portada-4x3.webp", "https://manualdecocina.com/recetas/leche-evaporada-casera/portada-16x9.webp"], "faq": [{"q": "Does it contain sugar?", "a": "No sugar is added, but natural milk sugars remain. It is not lactose-free."}, {"q": "Can I store it like an unopened can?", "a": "No. Home reduction concentrates milk but does not sterilize it for room-temperature storage."}], "additional_time_minutes": 60}, "published": false, "editorial_status": "ready"}, {"language": "de", "slug": "ungesuesste-kondensmilch-selber-machen", "public_path": "/de/ungesuesste-kondensmilch-selber-machen", "title": "Ungesüßte Kondensmilch selber machen", "excerpt": "Milch ohne Zuckerzusatz zu ungesüßter Kondensmilch einkochen. Mit Schrittfotos, Endvolumen, Kochzeit und Aufbewahrung für Saucen, Cremes und Desserts.", "summary": "Milch wird auf etwa 40 % ihres Anfangsvolumens reduziert. Ein Liter ergibt ungefähr 400 ml, ohne Zucker oder Mehl. Die hausgemachte Variante muss gekühlt werden und ist nicht wie Dosenmilch sterilisiert.", "content_html": "<p>Milch wird auf etwa 40 % ihres Anfangsvolumens reduziert. Ein Liter ergibt ungefähr 400 ml, ohne Zucker oder Mehl. Die hausgemachte Variante muss gekühlt werden und ist nicht wie Dosenmilch sterilisiert.</p>", "notes": "<h3>Tipps und Aufbewahrung</h3><p>Abgedeckt in 3–4 Tagen verbrauchen. Sie lässt sich nicht wie Sahne aufschlagen und ersetzt gezuckerte Kondensmilch nicht ohne Anpassung. Die Topfbreite beeinflusst die Zeit; entscheidend ist das Endvolumen. Nicht küchenerprobt. Enthält Milch. Saubere, desinfizierte Geräte verwenden und bei höchstens 4 °C lagern. Dies ist keine ungekühlt haltbare Konserve.</p><ul><li><a href=\"https://www.biggerbolderbaking.com/evaporated-milk-recipe/\">Bigger Bolder Baking — evaporated milk technique</a></li><li><a href=\"https://asbe.org/article/evaporated-milk/?topic=ingredient\">American Society of Baking — evaporated milk</a></li></ul>", "ingredients": [{"name": "pasteurisierte Vollmilch", "amount": "1000", "unit": "ml"}], "steps": [{"title": "Milch abmessen", "content": "Einen Liter in einen breiten Topf mit dickem Boden geben. Vorher prüfen, wie 400 ml im Topf aussehen, oder einen hitzefesten Messbecher bereithalten.", "image_url": "https://manualdecocina.com/recetas/leche-evaporada-casera/paso-01.webp", "image_alt": "Milch abmessen — Ungesüßte Kondensmilch selber machen"}, {"title": "Sanft reduzieren", "content": "Offen bei niedriger Hitze etwa 40–50 Minuten sehr leicht köcheln. Regelmäßig über den Boden rühren und entstehende Haut entfernen. Nicht anbrennen oder überkochen lassen.", "image_url": "https://manualdecocina.com/recetas/leche-evaporada-casera/paso-02.webp", "image_alt": "Sanft reduzieren — Ungesüßte Kondensmilch selber machen"}, {"title": "Prüfen und abkühlen", "content": "Nahe 400 ml das Volumen vorsichtig prüfen. Bei Bedarf weiter reduzieren, bei zu wenig Volumen etwas Milch ergänzen. Durch ein feines Sieb in einen sauberen Krug geben und im kalten Wasserbad ohne Wassereintritt abkühlen.", "image_url": "https://manualdecocina.com/recetas/leche-evaporada-casera/paso-03.webp", "image_alt": "Prüfen und abkühlen — Ungesüßte Kondensmilch selber machen"}, {"title": "Kühlen und verwenden", "content": "Innerhalb von 2 Stunden kalt stellen und etwa 1 Stunde abkühlen lassen. Vor Verwendung in Saucen oder Desserts umrühren. Die Milch ist cremiger, bleibt aber flüssig.", "image_url": "https://manualdecocina.com/recetas/leche-evaporada-casera/paso-04.webp", "image_alt": "Kühlen und verwenden — Ungesüßte Kondensmilch selber machen"}], "category": "Beilagen", "course": "Beilagen", "cuisine": "International", "difficulty": "Einfach", "prep_time_minutes": 5, "cook_time_minutes": 50, "total_time_minutes": 115, "servings": 8, "image_url": "https://manualdecocina.com/recetas/leche-evaporada-casera/portada.webp", "gallery": [{"url": "https://manualdecocina.com/recetas/leche-evaporada-casera/portada.webp", "alt": "Ungesüßte Kondensmilch selber machen"}], "video_urls": [], "keywords": ["Ungesüßte Kondensmilch selber machen"], "nutrition": {"calories": 79, "protein_g": 4.1, "carbs_g": 6.2, "fat_g": 4.2, "serving_size": "1 von 8 Portionen, etwa 50 ml", "estimated": true, "note": "Schätzung pro Portion; Ausbeute, Feuchtigkeit und Produkte beeinflussen die Werte.", "source": "USDA FoodData Central generic whole milk", "method": "1000 ml milk estimated as 1030 g × per-100-g profile (61 kcal,3.15 g protein,4.8 g carbohydrate,3.25 g fat), divided by 8 portions. Finished volume about 400 ml, 50 ml per portion. Only water evaporates; no whey drained. Rounded."}, "seo": {"title": "Ungesüßte Kondensmilch selber machen", "description": "Milch ohne Zuckerzusatz zu ungesüßter Kondensmilch einkochen. Mit Schrittfotos, Endvolumen, Kochzeit und Aufbewahrung für Saucen, Cremes und Desserts.", "author": "Néstor Bastidas", "image_alt": "Ungesüßte Kondensmilch selber machen", "image_variants": ["https://manualdecocina.com/recetas/leche-evaporada-casera/portada-1x1.webp", "https://manualdecocina.com/recetas/leche-evaporada-casera/portada-4x3.webp", "https://manualdecocina.com/recetas/leche-evaporada-casera/portada-16x9.webp"], "faq": [{"q": "Enthält sie Zucker?", "a": "Es wird kein Zucker zugesetzt, natürlicher Milchzucker bleibt enthalten. Sie ist nicht laktosefrei."}, {"q": "Ist sie wie eine verschlossene Dose haltbar?", "a": "Nein. Reduzieren konzentriert, sterilisiert aber nicht für ungekühlte Lagerung."}], "additional_time_minutes": 60}, "published": false, "editorial_status": "ready"}, {"language": "fr", "slug": "lait-concentre-non-sucre-maison", "public_path": "/fr/lait-concentre-non-sucre-maison", "title": "Lait concentré non sucré fait maison", "excerpt": "Concentrez du lait entier sans ajouter de sucre. Photos, volume final, temps de réduction et conservation au frais pour sauces, crèmes et desserts.", "summary": "Le lait réduit à environ 40 % de son volume initial : un litre donne environ 400 ml, sans sucre ajouté ni farine. Cette version maison doit être réfrigérée ; elle n'est pas stérilisée comme une conserve industrielle.", "content_html": "<p>Le lait réduit à environ 40 % de son volume initial : un litre donne environ 400 ml, sans sucre ajouté ni farine. Cette version maison doit être réfrigérée ; elle n&#x27;est pas stérilisée comme une conserve industrielle.</p>", "notes": "<h3>Conseils et conservation</h3><p>Gardez couvert et utilisez sous 3–4 jours. Il ne monte pas comme une crème et ne remplace pas le lait concentré sucré sans adaptation. La largeur de la casserole change le temps ; fiez-vous au volume final. Non testée en cuisine. Contient du lait. Utilisez du matériel propre et désinfecté et conservez à 4 °C maximum. Cette préparation ne se conserve pas à température ambiante.</p><ul><li><a href=\"https://www.biggerbolderbaking.com/evaporated-milk-recipe/\">Bigger Bolder Baking — evaporated milk technique</a></li><li><a href=\"https://asbe.org/article/evaporated-milk/?topic=ingredient\">American Society of Baking — evaporated milk</a></li></ul>", "ingredients": [{"name": "lait entier pasteurisé", "amount": "1000", "unit": "ml"}], "steps": [{"title": "Mesurez le lait", "content": "Versez le litre dans une casserole large à fond épais. Repérez d'abord le niveau de 400 ml dans la casserole ou préparez un verre doseur résistant à la chaleur.", "image_url": "https://manualdecocina.com/recetas/leche-evaporada-casera/paso-01.webp", "image_alt": "Mesurez le lait — Lait concentré non sucré fait maison"}, {"title": "Réduisez doucement", "content": "Chauffez à découvert à feu doux pendant environ 40–50 minutes, au léger frémissement. Remuez souvent le fond et retirez la peau éventuelle. Évitez brûlure et débordement.", "image_url": "https://manualdecocina.com/recetas/leche-evaporada-casera/paso-02.webp", "image_alt": "Réduisez doucement — Lait concentré non sucré fait maison"}, {"title": "Vérifiez et refroidissez", "content": "Près de 400 ml, vérifiez le volume avec précaution. Réduisez encore si nécessaire ou ajoutez un peu de lait si trop concentré. Filtrez dans un récipient propre et refroidissez au bain d'eau froide sans entrée d'eau.", "image_url": "https://manualdecocina.com/recetas/leche-evaporada-casera/paso-03.webp", "image_alt": "Vérifiez et refroidissez — Lait concentré non sucré fait maison"}, {"title": "Réfrigérez et utilisez", "content": "Réfrigérez avant 2 heures et laissez refroidir environ 1 heure. Remuez avant de préparer sauces ou desserts. La texture est plus crémeuse que le lait mais reste liquide.", "image_url": "https://manualdecocina.com/recetas/leche-evaporada-casera/paso-04.webp", "image_alt": "Réfrigérez et utilisez — Lait concentré non sucré fait maison"}], "category": "Accompagnements", "course": "Accompagnements", "cuisine": "Internationale", "difficulty": "Facile", "prep_time_minutes": 5, "cook_time_minutes": 50, "total_time_minutes": 115, "servings": 8, "image_url": "https://manualdecocina.com/recetas/leche-evaporada-casera/portada.webp", "gallery": [{"url": "https://manualdecocina.com/recetas/leche-evaporada-casera/portada.webp", "alt": "Lait concentré non sucré fait maison"}], "video_urls": [], "keywords": ["Lait concentré non sucré fait maison"], "nutrition": {"calories": 79, "protein_g": 4.1, "carbs_g": 6.2, "fat_g": 4.2, "serving_size": "1 des 8 portions, environ 50 ml", "estimated": true, "note": "Estimation par portion ; rendement, humidité et marques modifient les valeurs.", "source": "USDA FoodData Central generic whole milk", "method": "1000 ml milk estimated as 1030 g × per-100-g profile (61 kcal,3.15 g protein,4.8 g carbohydrate,3.25 g fat), divided by 8 portions. Finished volume about 400 ml, 50 ml per portion. Only water evaporates; no whey drained. Rounded."}, "seo": {"title": "Lait concentré non sucré fait maison", "description": "Concentrez du lait entier sans ajouter de sucre. Photos, volume final, temps de réduction et conservation au frais pour sauces, crèmes et desserts.", "author": "Néstor Bastidas", "image_alt": "Lait concentré non sucré fait maison", "image_variants": ["https://manualdecocina.com/recetas/leche-evaporada-casera/portada-1x1.webp", "https://manualdecocina.com/recetas/leche-evaporada-casera/portada-4x3.webp", "https://manualdecocina.com/recetas/leche-evaporada-casera/portada-16x9.webp"], "faq": [{"q": "Contient-il du sucre ?", "a": "Sans sucre ajouté, il garde les sucres naturels du lait. Il n'est pas sans lactose."}, {"q": "Se conserve-t-il comme une boîte fermée ?", "a": "Non. La réduction maison concentre le lait mais ne le stérilise pas pour une conservation ambiante."}], "additional_time_minutes": 60}, "published": false, "editorial_status": "ready"}, {"language": "it", "slug": "latte-evaporato-fatto-in-casa", "public_path": "/it/latte-evaporato-fatto-in-casa", "title": "Latte evaporato fatto in casa senza zucchero aggiunto", "excerpt": "Prepara latte evaporato riducendo latte intero senza zucchero aggiunto. Foto, volume finale, tempi e conservazione per salse, creme e dolci fatti in casa.", "summary": "Il latte si concentra fino a circa il 40% del volume iniziale. Un litro rende circa 400 ml senza zucchero aggiunto né farina. Questa versione va refrigerata e non è sterilizzata come il prodotto in lattina.", "content_html": "<p>Il latte si concentra fino a circa il 40% del volume iniziale. Un litro rende circa 400 ml senza zucchero aggiunto né farina. Questa versione va refrigerata e non è sterilizzata come il prodotto in lattina.</p>", "notes": "<h3>Consigli e conservazione</h3><p>Conserva coperto e usa entro 3–4 giorni. Non monta come panna e non sostituisce latte condensato zuccherato senza adattamenti. La larghezza della pentola cambia i tempi: conta il volume finale. Non testato in cucina. Contiene latte. Usa utensili puliti e igienizzati e conserva a 4 °C o meno. Non è una conserva da tenere a temperatura ambiente.</p><ul><li><a href=\"https://www.biggerbolderbaking.com/evaporated-milk-recipe/\">Bigger Bolder Baking — evaporated milk technique</a></li><li><a href=\"https://asbe.org/article/evaporated-milk/?topic=ingredient\">American Society of Baking — evaporated milk</a></li></ul>", "ingredients": [{"name": "latte intero pastorizzato", "amount": "1000", "unit": "ml"}], "steps": [{"title": "Misura il latte", "content": "Versa il litro in una casseruola larga a fondo spesso. Controlla prima il livello di 400 ml nella pentola oppure prepara una caraffa graduata resistente al calore.", "image_url": "https://manualdecocina.com/recetas/leche-evaporada-casera/paso-01.webp", "image_alt": "Misura il latte — Latte evaporato fatto in casa senza zucchero aggiunto"}, {"title": "Riduci dolcemente", "content": "Cuoci scoperto a fuoco basso per circa 40–50 minuti, sobbollendo appena. Mescola spesso sul fondo e togli l'eventuale pellicina. Evita che bruci o trabocchi.", "image_url": "https://manualdecocina.com/recetas/leche-evaporada-casera/paso-02.webp", "image_alt": "Riduci dolcemente — Latte evaporato fatto in casa senza zucchero aggiunto"}, {"title": "Controlla e raffredda", "content": "Vicino ai 400 ml, misura con attenzione. Riduci ancora se serve o aggiungi poco latte se hai esagerato. Filtra in una caraffa pulita e raffredda in acqua fredda senza farla entrare.", "image_url": "https://manualdecocina.com/recetas/leche-evaporada-casera/paso-03.webp", "image_alt": "Controlla e raffredda — Latte evaporato fatto in casa senza zucchero aggiunto"}, {"title": "Refrigera e usa", "content": "Metti in frigo entro 2 ore e lascia raffreddare circa 1 ora. Mescola prima di usare in salse o dolci. È più cremoso del latte ma resta liquido.", "image_url": "https://manualdecocina.com/recetas/leche-evaporada-casera/paso-04.webp", "image_alt": "Refrigera e usa — Latte evaporato fatto in casa senza zucchero aggiunto"}], "category": "Contorni", "course": "Contorni", "cuisine": "Internazionale", "difficulty": "Facile", "prep_time_minutes": 5, "cook_time_minutes": 50, "total_time_minutes": 115, "servings": 8, "image_url": "https://manualdecocina.com/recetas/leche-evaporada-casera/portada.webp", "gallery": [{"url": "https://manualdecocina.com/recetas/leche-evaporada-casera/portada.webp", "alt": "Latte evaporato fatto in casa senza zucchero aggiunto"}], "video_urls": [], "keywords": ["Latte evaporato fatto in casa senza zucchero aggiunto"], "nutrition": {"calories": 79, "protein_g": 4.1, "carbs_g": 6.2, "fat_g": 4.2, "serving_size": "1 di 8 porzioni, circa 50 ml", "estimated": true, "note": "Stima per porzione; resa, umidità e prodotti possono cambiare i valori.", "source": "USDA FoodData Central generic whole milk", "method": "1000 ml milk estimated as 1030 g × per-100-g profile (61 kcal,3.15 g protein,4.8 g carbohydrate,3.25 g fat), divided by 8 portions. Finished volume about 400 ml, 50 ml per portion. Only water evaporates; no whey drained. Rounded."}, "seo": {"title": "Latte evaporato fatto in casa senza zucchero aggiunto", "description": "Prepara latte evaporato riducendo latte intero senza zucchero aggiunto. Foto, volume finale, tempi e conservazione per salse, creme e dolci fatti in casa.", "author": "Néstor Bastidas", "image_alt": "Latte evaporato fatto in casa senza zucchero aggiunto", "image_variants": ["https://manualdecocina.com/recetas/leche-evaporada-casera/portada-1x1.webp", "https://manualdecocina.com/recetas/leche-evaporada-casera/portada-4x3.webp", "https://manualdecocina.com/recetas/leche-evaporada-casera/portada-16x9.webp"], "faq": [{"q": "Contiene zucchero?", "a": "Non si aggiunge zucchero ma restano gli zuccheri naturali del latte. Non è senza lattosio."}, {"q": "Si conserva come una lattina chiusa?", "a": "No. La riduzione domestica concentra il latte ma non lo sterilizza per conservarlo fuori dal frigo."}], "additional_time_minutes": 60}, "published": false, "editorial_status": "ready"}, {"language": "ja", "slug": "homemade-unsweetened-evaporated-milk", "public_path": "/ja/homemade-unsweetened-evaporated-milk", "title": "砂糖を加えずに作る自家製無糖練乳", "excerpt": "牛乳を弱火で煮詰めて作る自家製無糖練乳。工程写真で仕上がりの量、煮詰め時間、冷却と冷蔵保存を説明します。ソースやスープ、お菓子に使える濃縮乳の基本です。", "summary": "牛乳を元の約40％の量まで煮詰めます。1 Lから約400 mlでき、砂糖や小麦粉は加えません。市販缶のような滅菌処理はしていないため、必ず冷蔵します。", "content_html": "<p>牛乳を元の約40％の量まで煮詰めます。1 Lから約400 mlでき、砂糖や小麦粉は加えません。市販缶のような滅菌処理はしていないため、必ず冷蔵します。</p>", "notes": "<h3>コツと保存</h3><p>ふたをして3〜4日以内に使います。生クリームのようには泡立ちません。加糖練乳とは配合調整なしに置き換えられません。鍋の広さで時間は変わるので、最終の量を目安にします。調理試験は行っていません。 乳を含みます。清潔に洗浄・消毒した器具を使い、4 ℃以下で冷蔵してください。常温保存用の瓶詰めではありません。</p><ul><li><a href=\"https://www.biggerbolderbaking.com/evaporated-milk-recipe/\">Bigger Bolder Baking — evaporated milk technique</a></li><li><a href=\"https://asbe.org/article/evaporated-milk/?topic=ingredient\">American Society of Baking — evaporated milk</a></li></ul>", "ingredients": [{"name": "殺菌済みの全乳", "amount": "1000", "unit": "ml"}], "steps": [{"title": "牛乳を量る", "content": "厚手の広い鍋に牛乳1 Lを入れます。先に鍋で400 mlの高さを確認するか、耐熱の計量カップを用意します。", "image_url": "https://manualdecocina.com/recetas/leche-evaporada-casera/paso-01.webp", "image_alt": "牛乳を量る — 砂糖を加えずに作る自家製無糖練乳"}, {"title": "静かに煮詰める", "content": "ふたをせず弱火で40〜50分、わずかに煮立つ程度に加熱します。鍋底をこまめに混ぜ、膜が出たら取り除きます。焦げや吹きこぼれに注意します。", "image_url": "https://manualdecocina.com/recetas/leche-evaporada-casera/paso-02.webp", "image_alt": "静かに煮詰める — 砂糖を加えずに作る自家製無糖練乳"}, {"title": "量を確認して冷ます", "content": "400 ml近くになったら慎重に量を確認します。多ければさらに煮詰め、減りすぎたら牛乳を少量足します。清潔な容器に細かいざるでこし、冷水を中へ入れず外側から冷まします。", "image_url": "https://manualdecocina.com/recetas/leche-evaporada-casera/paso-03.webp", "image_alt": "量を確認して冷ます — 砂糖を加えずに作る自家製無糖練乳"}, {"title": "冷蔵して使う", "content": "2時間以内に冷蔵し、約1時間冷まします。ソースやお菓子に使う前に混ぜます。普通の牛乳より濃厚ですが、液状です。", "image_url": "https://manualdecocina.com/recetas/leche-evaporada-casera/paso-04.webp", "image_alt": "冷蔵して使う — 砂糖を加えずに作る自家製無糖練乳"}], "category": "付け合わせ", "course": "付け合わせ", "cuisine": "各国料理", "difficulty": "簡単", "prep_time_minutes": 5, "cook_time_minutes": 50, "total_time_minutes": 115, "servings": 8, "image_url": "https://manualdecocina.com/recetas/leche-evaporada-casera/portada.webp", "gallery": [{"url": "https://manualdecocina.com/recetas/leche-evaporada-casera/portada.webp", "alt": "砂糖を加えずに作る自家製無糖練乳"}], "video_urls": [], "keywords": ["砂糖を加えずに作る自家製無糖練乳"], "nutrition": {"calories": 79, "protein_g": 4.1, "carbs_g": 6.2, "fat_g": 4.2, "serving_size": "8食分の1、約50 ml", "estimated": true, "note": "1食分の推定値です。出来上がり量、水分、製品により異なります。", "source": "USDA FoodData Central generic whole milk", "method": "1000 ml milk estimated as 1030 g × per-100-g profile (61 kcal,3.15 g protein,4.8 g carbohydrate,3.25 g fat), divided by 8 portions. Finished volume about 400 ml, 50 ml per portion. Only water evaporates; no whey drained. Rounded."}, "seo": {"title": "砂糖を加えずに作る自家製無糖練乳", "description": "牛乳を弱火で煮詰めて作る自家製無糖練乳。工程写真で仕上がりの量、煮詰め時間、冷却と冷蔵保存を説明します。ソースやスープ、お菓子に使える濃縮乳の基本です。", "author": "Néstor Bastidas", "image_alt": "砂糖を加えずに作る自家製無糖練乳", "image_variants": ["https://manualdecocina.com/recetas/leche-evaporada-casera/portada-1x1.webp", "https://manualdecocina.com/recetas/leche-evaporada-casera/portada-4x3.webp", "https://manualdecocina.com/recetas/leche-evaporada-casera/portada-16x9.webp"], "faq": [{"q": "砂糖は含まれますか。", "a": "砂糖は加えませんが、牛乳由来の糖は残ります。乳糖ゼロではありません。"}, {"q": "未開封の缶のように保存できますか。", "a": "いいえ。家庭での煮詰めは濃縮であり、常温保存用の滅菌ではありません。"}], "additional_time_minutes": 60}, "published": false, "editorial_status": "ready"}, {"language": "pt", "slug": "leite-evaporado-caseiro", "public_path": "/pt/leite-evaporado-caseiro", "title": "Leite evaporado caseiro sem açúcar adicionado", "excerpt": "Faça leite evaporado reduzindo leite integral sem açúcar. Fotos, volume final, tempo de cozimento e conservação para usar em molhos, cremes e sobremesas.", "summary": "O leite reduz até cerca de 40% do volume inicial. Um litro rende aproximadamente 400 ml, sem açúcar adicionado ou farinha. A versão caseira precisa de geladeira e não é esterilizada como uma lata comercial.", "content_html": "<p>O leite reduz até cerca de 40% do volume inicial. Um litro rende aproximadamente 400 ml, sem açúcar adicionado ou farinha. A versão caseira precisa de geladeira e não é esterilizada como uma lata comercial.</p>", "notes": "<h3>Dicas e conservação</h3><p>Conserve tampado e use em 3–4 dias. Não bate como creme e não substitui leite condensado açucarado sem ajustes. A largura da panela muda o tempo; siga o volume final. Sem teste de cozinha próprio. Contém leite. Use utensílios limpos e higienizados e conserve a 4 °C ou menos. Não é uma conserva para guardar à temperatura ambiente.</p><ul><li><a href=\"https://www.biggerbolderbaking.com/evaporated-milk-recipe/\">Bigger Bolder Baking — evaporated milk technique</a></li><li><a href=\"https://asbe.org/article/evaporated-milk/?topic=ingredient\">American Society of Baking — evaporated milk</a></li></ul>", "ingredients": [{"name": "leite integral pasteurizado", "amount": "1000", "unit": "ml"}], "steps": [{"title": "Meça o leite", "content": "Coloque o litro numa panela larga de fundo grosso. Antes, veja o nível de 400 ml nessa panela ou prepare uma jarra graduada resistente ao calor.", "image_url": "https://manualdecocina.com/recetas/leche-evaporada-casera/paso-01.webp", "image_alt": "Meça o leite — Leite evaporado caseiro sem açúcar adicionado"}, {"title": "Reduza devagar", "content": "Aqueça destampado em fogo baixo por cerca de 40–50 minutos, com fervura muito suave. Mexa o fundo frequentemente e retire a película se aparecer. Não deixe queimar nem transbordar.", "image_url": "https://manualdecocina.com/recetas/leche-evaporada-casera/paso-02.webp", "image_alt": "Reduza devagar — Leite evaporado caseiro sem açúcar adicionado"}, {"title": "Confira e esfrie", "content": "Perto de 400 ml, confira o volume com cuidado. Reduza mais se necessário ou acrescente leite se reduziu demais. Coe para jarra limpa e esfrie em banho de água fria sem entrar água.", "image_url": "https://manualdecocina.com/recetas/leche-evaporada-casera/paso-03.webp", "image_alt": "Confira e esfrie — Leite evaporado caseiro sem açúcar adicionado"}, {"title": "Refrigere e use", "content": "Leve à geladeira antes de 2 horas e deixe esfriar cerca de 1 hora. Mexa antes de usar em molhos ou doces. Fica mais cremoso que leite, mas continua líquido.", "image_url": "https://manualdecocina.com/recetas/leche-evaporada-casera/paso-04.webp", "image_alt": "Refrigere e use — Leite evaporado caseiro sem açúcar adicionado"}], "category": "Acompanhamentos", "course": "Acompanhamentos", "cuisine": "Internacional", "difficulty": "Fácil", "prep_time_minutes": 5, "cook_time_minutes": 50, "total_time_minutes": 115, "servings": 8, "image_url": "https://manualdecocina.com/recetas/leche-evaporada-casera/portada.webp", "gallery": [{"url": "https://manualdecocina.com/recetas/leche-evaporada-casera/portada.webp", "alt": "Leite evaporado caseiro sem açúcar adicionado"}], "video_urls": [], "keywords": ["Leite evaporado caseiro sem açúcar adicionado"], "nutrition": {"calories": 79, "protein_g": 4.1, "carbs_g": 6.2, "fat_g": 4.2, "serving_size": "1 de 8 porções, cerca de 50 ml", "estimated": true, "note": "Estimativa por porção; rendimento, umidade e marcas alteram os valores.", "source": "USDA FoodData Central generic whole milk", "method": "1000 ml milk estimated as 1030 g × per-100-g profile (61 kcal,3.15 g protein,4.8 g carbohydrate,3.25 g fat), divided by 8 portions. Finished volume about 400 ml, 50 ml per portion. Only water evaporates; no whey drained. Rounded."}, "seo": {"title": "Leite evaporado caseiro sem açúcar adicionado", "description": "Faça leite evaporado reduzindo leite integral sem açúcar. Fotos, volume final, tempo de cozimento e conservação para usar em molhos, cremes e sobremesas.", "author": "Néstor Bastidas", "image_alt": "Leite evaporado caseiro sem açúcar adicionado", "image_variants": ["https://manualdecocina.com/recetas/leche-evaporada-casera/portada-1x1.webp", "https://manualdecocina.com/recetas/leche-evaporada-casera/portada-4x3.webp", "https://manualdecocina.com/recetas/leche-evaporada-casera/portada-16x9.webp"], "faq": [{"q": "Tem açúcar?", "a": "Não se adiciona açúcar, mas os açúcares naturais do leite permanecem. Não é sem lactose."}, {"q": "Posso guardar como lata fechada?", "a": "Não. A redução caseira concentra o leite, mas não o esteriliza para guardar fora da geladeira."}], "additional_time_minutes": 60}, "published": false, "editorial_status": "ready"}]$payload$::jsonb;
foods jsonb := $foods$[]$foods$::jsonb;
aliases jsonb := $aliases$[{"slug": "leche", "alias": "leche entera pasteurizada"}]$aliases$::jsonb;
x jsonb; a jsonb; v public.recipes; made public.recipes; source_id uuid; group_id uuid;
BEGIN
PERFORM set_config('request.jwt.claim.sub','2caf0bab-d7e8-4d52-9910-d79799c27072',true);
IF NOT public.is_admin() THEN RAISE EXCEPTION 'Admin context missing'; END IF;
IF jsonb_array_length(payload)<>7 THEN RAISE EXCEPTION 'Need seven languages'; END IF;
IF EXISTS(SELECT 1 FROM public.recipes r JOIN jsonb_array_elements(payload) e ON r.public_path=e->>'public_path' OR (r.language=e->>'language' AND r.slug=e->>'slug')) THEN RAISE EXCEPTION 'Recipe already exists'; END IF;
IF EXISTS(SELECT 1 FROM public.content_pages p JOIN jsonb_array_elements(payload) e ON p.public_path=e->>'public_path') OR EXISTS(SELECT 1 FROM public.content_redirects r JOIN jsonb_array_elements(payload) e ON r.source_path=e->>'public_path') THEN RAISE EXCEPTION 'Route collision'; END IF;
FOR a IN SELECT value FROM jsonb_array_elements(foods) LOOP
 INSERT INTO public.ingredients(slug,name,normalized_name,description,status,searchable,indexable)
 SELECT a->>'slug',a->>'name',lower(a->>'name'),'Ingrediente para elaboraciones lácteas domésticas.','canonical',true,false WHERE NOT EXISTS(SELECT 1 FROM public.ingredients WHERE slug=a->>'slug');
END LOOP;
FOR a IN SELECT value FROM jsonb_array_elements(aliases) LOOP
 IF NOT EXISTS(SELECT 1 FROM public.ingredients WHERE slug=a->>'slug' AND status='canonical') THEN RAISE EXCEPTION 'Missing ingredient %',a; END IF;
 IF EXISTS(SELECT 1 FROM public.ingredient_aliases ia JOIN public.ingredients i ON i.id=ia.ingredient_id WHERE lower(trim(ia.alias))=lower(trim(a->>'alias')) AND i.slug<>a->>'slug' AND i.status='canonical') THEN RAISE EXCEPTION 'Alias collision %',a; END IF;
 INSERT INTO public.ingredient_aliases(ingredient_id,alias,normalized_alias) SELECT id,a->>'alias',lower(a->>'alias') FROM public.ingredients WHERE slug=a->>'slug' AND status='canonical' ON CONFLICT(ingredient_id,normalized_alias) DO NOTHING;
END LOOP;
FOR x IN SELECT value FROM jsonb_array_elements(payload) LOOP
 v:=jsonb_populate_record(NULL::public.recipes,x);
 IF v.language='es' THEN
  made:=public.create_recipe(v.language,v.slug,v.title,v.excerpt,v.ingredients,v.steps,v.category,v.prep_time_minutes,v.cook_time_minutes,v.servings,v.image_url,false,v.public_path);
  source_id:=made.id;group_id:=made.recipe_group_id;
 ELSE
  made:=public.create_recipe_translation(source_id,v.language,v.slug,v.title,v.excerpt,v.ingredients,v.steps,v.category,v.prep_time_minutes,v.cook_time_minutes,v.servings,v.image_url,false,v.public_path);
 END IF;
 UPDATE public.recipes SET content_html=v.content_html,summary=v.summary,notes=v.notes,difficulty=v.difficulty,course=v.course,cuisine=v.cuisine,total_time_minutes=v.total_time_minutes,keywords=v.keywords,nutrition=v.nutrition,gallery=v.gallery,video_urls=v.video_urls,seo=v.seo,editorial_status='ready',ready_at=now() WHERE id=made.id;
END LOOP;
IF (SELECT count(*) FROM public.recipes WHERE recipe_group_id=group_id)<>7 THEN RAISE EXCEPTION 'Incomplete group'; END IF;
IF (SELECT count(*) FROM public.recipe_ingredients WHERE recipe_id=source_id)<>1 OR EXISTS(SELECT 1 FROM public.recipe_ingredient_pending WHERE recipe_id=source_id) THEN RAISE EXCEPTION 'Unresolved ingredients'; END IF;
FOR v IN SELECT * FROM public.recipes WHERE recipe_group_id=group_id LOOP
 PERFORM public.update_recipe(v.id,v.slug,v.title,v.excerpt,v.ingredients,v.steps,v.category,v.prep_time_minutes,v.cook_time_minutes,v.servings,v.image_url,true);
 UPDATE public.recipes SET editorial_status='published' WHERE id=v.id;
END LOOP;
END $dairy$;
SELECT language,public_path,published FROM public.recipes WHERE recipe_group_id=(SELECT recipe_group_id FROM public.recipes WHERE language='es' AND slug='leche-evaporada-casera') ORDER BY language;
